<pre><code>using EntityFrameworkProject.Data;
using EntityFrameworkProject.Models;
using EntityFrameworkProject.ViewModels;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EntityFrameworkProject.Controllers
{
    public class ProductController : Controller
    {
        private readonly AppDbContext _context;

        public ProductController(AppDbContext context)
        {
            _context = context;
        }

        public async Task&lt;IActionResult&gt; Index()
        {
            IEnumerable&lt;Product&gt; products = await _context.Products
                .Include(m =&gt; m.ProductImages)
                .Include(m =&gt; m.Category)
                //.Take(4)
                .Where(m =&gt; !m.IsDeleted).ToListAsync();

            IEnumerable&lt;Category&gt; categories = await _context.Categories
                .Include(m =&gt; m.Products)
                .Where(m =&gt; !m.IsDeleted)
                .ToListAsync();

            HomeVM homeVM = new()
            {
                Products = products,
                Categories = categories
            };

            return View(homeVM);
        }

        public async Task&lt;IActionResult&gt; Search(string? searchtext)
        {
            IEnumerable&lt;Product&gt; products = await _context.Products
.Include(m =&gt; m.ProductImages)
.Include(m =&gt; m.Category)
.Where(m =&gt; !m.IsDeleted &amp;&amp; m.Name.Contains(searchtext) || searchtext == null)
.ToListAsync();

            HomeVM homeVM = new()
            {
                Products = products
            };

            return PartialView(&quot;_ProductPartial&quot;, homeVM);
        }

        public async Task&lt;IActionResult&gt; CategoryFilter(int categoryId)
        {
            IEnumerable&lt;Product&gt; products = await _context.Products
.Include(m =&gt; m.ProductImages)
.Include(m =&gt; m.Category)
.Where(m =&gt; !m.IsDeleted &amp;&amp; m.CategoryId == categoryId)
.ToListAsync();

            HomeVM homeVM = new()
            {
                Products = products
            };

            return PartialView(&quot;_ProductPartial&quot;, homeVM);
        }

        public async Task&lt;IActionResult&gt; Sorting(string sortingType)
        {
            IEnumerable&lt;Product&gt; products = await _context.Products
.Include(m =&gt; m.ProductImages)
.Include(m =&gt; m.Category)
.Where(m =&gt; !m.IsDeleted)
.ToListAsync();

            switch (sortingType)
            {
                case &quot;lowToHigh&quot;:
                    products = products.OrderBy(m =&gt; m.Price);
                    break;

                case &quot;highToLow&quot;:
                    products = products.OrderByDescending(m =&gt; m.Price);
                    break;

                case &quot;AZ&quot;:
                    products = products.OrderBy(m =&gt; m.Name);
                    break;

                case &quot;ZA&quot;:
                    products = products.OrderByDescending(m =&gt; m.Name);
                    break;

                default:
                    break;
            }

            HomeVM homeVM = new()
            {
                Products = products
            };

            return PartialView(&quot;_ProductPartial&quot;, homeVM);
        }
    }
}
