<pre><code>using EntityFrameworkProject.Enums;
using EntityFrameworkProject.Models;
using EntityFrameworkProject.Services.Interfaces;
using EntityFrameworkProject.ViewModels.AccountVMs;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;

namespace EntityFrameworkProject.Controllers
{
    public class AccountController : Controller
    {
        private readonly UserManager&lt;AppUser&gt; _userManager;
        private readonly SignInManager&lt;AppUser&gt; _signInManager;
        private readonly RoleManager&lt;IdentityRole&gt; _roleManager;
        private readonly IFileService _fileService;
        private readonly IEmailService _emailService;

        public AccountController(UserManager&lt;AppUser&gt; userManager, SignInManager&lt;AppUser&gt; signInManager, IFileService fileService, IEmailService emailService, RoleManager&lt;IdentityRole&gt; roleManager)
        {
            _userManager = userManager;
            _signInManager = signInManager;
            _fileService = fileService;
            _emailService = emailService;
            _roleManager = roleManager;
        }

        public async Task&lt;IActionResult&gt; Update()
        {
            if (!User.Identity.IsAuthenticated)
            {
                return RedirectToAction(nameof(Login));
            }

            AppUser? appUser = await _userManager.FindByNameAsync(User.Identity.Name);

            UpdateUserVM updateUserVM = new()
            {
                Name = appUser.Name,
                Surname = appUser.Surname,
                Username = appUser.UserName,
                Email = appUser.Email
            };

            return View(updateUserVM);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task&lt;IActionResult&gt; Update(UpdateUserVM request)
        {
            if (!ModelState.IsValid) return View(request);

            if (!User.Identity.IsAuthenticated)
            {
                return RedirectToAction(nameof(Login));
            }

            AppUser? appUser = await _userManager.FindByNameAsync(User.Identity.Name);

            appUser.Name = request.Name;
            appUser.Surname = request.Surname;
            appUser.UserName = request.Username;
            appUser.Email = request.Email;

            IdentityResult result = await _userManager.UpdateAsync(appUser);

            if (!result.Succeeded)
            {
                foreach (var error in result.Errors)
                {
                    ModelState.AddModelError(&quot;&quot;, error.Description);
                }

                return View(request);
            }

            if (request.OldPassword != null &amp;&amp; request.NewPassword != null &amp;&amp; request.ConfirmPassword != null)
            {
                IdentityResult identityResult = await _userManager
                    .ChangePasswordAsync(appUser, request.OldPassword, request.NewPassword);

                if (!identityResult.Succeeded)
                {
                    foreach (var error in identityResult.Errors)
                    {
                        ModelState.AddModelError(&quot;&quot;, error.Description);
                    }

                    return View(request);
                }
            }

            await _signInManager.SignOutAsync();

            return RedirectToAction(nameof(Login));
        }

        public IActionResult Register()
        {
            return View();
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task&lt;IActionResult&gt; Register(RegisterVM request)
        {
            if (!ModelState.IsValid) return View(request);

            AppUser appUser = new()
            {
                Name = request.Name,
                Surname = request.Surname,
                UserName = request.Username,
                Email = request.Email
            };

            IdentityResult result = await _userManager.CreateAsync(appUser, request.Password);

            if (!result.Succeeded)
            {
                foreach (var error in result.Errors)
                {
                    ModelState.AddModelError(&quot;&quot;, error.Description);
                }

                return View(request);
            }

            await _userManager.AddToRoleAsync(appUser, Roles.Member.ToString());

            string token = await _userManager.GenerateEmailConfirmationTokenAsync(appUser);

            string? confirmationLink = Url.Action(&quot;ConfirmEmail&quot;, &quot;Account&quot;,
                new { userId = appUser.Id, token }, Request.Scheme);

            string emailBody = await _fileService.ReadFile(&quot;wwwroot/template/verify.html&quot;);

            emailBody = emailBody.Replace(&quot;{{link}}&quot;, confirmationLink);
            emailBody = emailBody.Replace(&quot;{{name}}&quot;, appUser.Name);
            emailBody = emailBody.Replace(&quot;{{surname}}&quot;, appUser.Surname);

            _emailService.Send(appUser.Email, &quot;Confirm your email&quot;, emailBody);

            return RedirectToAction(nameof(CheckEmail));
        }

        public async Task&lt;IActionResult&gt; ConfirmEmail(string userId, string token)
        {
            AppUser? appUser = await _userManager.FindByIdAsync(userId);

            if (appUser == null) return NotFound();

            IdentityResult result = await _userManager.ConfirmEmailAsync(appUser, token);

            if (!result.Succeeded)
            {
                return BadRequest();
            }

            return RedirectToAction(nameof(Login));
        }

        public IActionResult CheckEmail()
        {
            return View();
        }

        public IActionResult ForgetPassword()
        {
            return View();
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task&lt;IActionResult&gt; ForgetPassword(ForgetPasswordVM request)
        {
            if (!ModelState.IsValid) return View(request);

            AppUser? appUser = await _userManager.FindByEmailAsync(request.Email);

            if (appUser == null)
            {
                ModelState.AddModelError(&quot;&quot;, &quot;User not found!&quot;);
                return View(request);
            }

            string token = await _userManager.GeneratePasswordResetTokenAsync(appUser);

            string? resetLink = Url.Action(&quot;ResetPassword&quot;, &quot;Account&quot;,
                new { userId = appUser.Id, token }, Request.Scheme);

            string emailBody = await _fileService.ReadFile(&quot;wwwroot/template/verify.html&quot;);

            emailBody = emailBody.Replace(&quot;{{link}}&quot;, resetLink);
            emailBody = emailBody.Replace(&quot;{{name}}&quot;, appUser.Name);
            emailBody = emailBody.Replace(&quot;{{surname}}&quot;, appUser.Surname);

            _emailService.Send(appUser.Email, &quot;Reset your password&quot;, emailBody);

            return RedirectToAction(nameof(CheckEmail));
        }

        public IActionResult ResetPassword(string userId, string token)
        {
            ResetPasswordVM resetPasswordVM = new()
            {
                UserId = userId,
                Token = token
            };

            return View(resetPasswordVM);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task&lt;IActionResult&gt; ResetPassword(ResetPasswordVM request)
        {
            if (!ModelState.IsValid) return View(request);

            AppUser? appUser = await _userManager.FindByIdAsync(request.UserId);

            if (appUser == null)
            {
                ModelState.AddModelError(&quot;&quot;, &quot;User not found!&quot;);
                return View(request);
            }

            bool checkPassword = await _userManager.CheckPasswordAsync(appUser, request.NewPassword);

            if (checkPassword)
            {
                ModelState.AddModelError(&quot;&quot;, &quot;Cant assign Old Password!&quot;);
                return View(request);
            }

            IdentityResult result = await _userManager.ResetPasswordAsync(appUser, request.Token, request.NewPassword);

            if (!result.Succeeded)
            {
                foreach (var error in result.Errors)
                {
                    ModelState.AddModelError(&quot;&quot;, error.Description);
                }

                return View(request);
            }

            return RedirectToAction(nameof(Login));
        }

        public IActionResult Login()
        {
            return View();
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task&lt;IActionResult&gt; Login(LoginVM request)
        {
            if (!ModelState.IsValid) return View(request);

            AppUser? appUser = await _userManager.FindByNameAsync(request.UsernameOrEmail);

            if (appUser == null)
            {
                appUser = await _userManager.FindByEmailAsync(request.UsernameOrEmail);
            }

            if (appUser == null)
            {
                ModelState.AddModelError(&quot;&quot;, &quot;Username or Password wrong!&quot;);
                return View(request);
            }

            var signInResult = await _signInManager.PasswordSignInAsync(appUser, request.Password, false, false);

            if (!signInResult.Succeeded)
            {
                ModelState.AddModelError(&quot;&quot;, &quot;Username or Password wrong!&quot;);
                return View(request);
            }
            else
            {
                await _signInManager.SignInAsync(appUser, false);
            }

            return RedirectToAction(&quot;Index&quot;, &quot;Home&quot;);
        }

        public async Task&lt;IActionResult&gt; Logout()
        {
            await _signInManager.SignOutAsync();
            return RedirectToAction(&quot;Index&quot;, &quot;Home&quot;);
        }

        public async Task&lt;IActionResult&gt; CreateRoles()
        {
            foreach (var role in Enum.GetValues&lt;Roles&gt;())
            {
                if (!await _roleManager.RoleExistsAsync(role.ToString()))
                {
                    await _roleManager.CreateAsync(new IdentityRole { Name = role.ToString() });
                }
                else
                {
                    return Json($&quot;{role} role already exists!&quot;);
                }
            }

            return Json(&quot;Successfully create roles!&quot;);
        }
    }
}
</code></pre>

Q: need help understanding for...of loop A: <p><code>for...of</code> just gives you each value from the array, not a reference to the array itself.</p>
<p>In this loop:</p>
<pre><code>for (let num of numbers) {
  num *= num;
  console.log(num);
}
</code></pre>
<p><code>num *= num</code> is the same as <code>num = num * num</code>, which squares the current value and logs it. That’s why your code works and produces the correct output. It doesn’t affect the original <code>numbers</code> array because <code>num</code> is just a local variable.</p>
<p>The reason your teacher’s solution uses:</p>
<pre><code>for (let num of numbers) {
  console.log(num * num);
}
</code></pre>
<p>is because there’s no need to modify <code>num</code>. You can calculate the square and log it directly, which is clearer and avoids reassigning the variable.</p>
<p><code>NaN</code> would only occur if <code>num</code> wasn’t a number. Since the array contains numbers, <code>num * num</code> is valid.</p>
<p>Your approach isn’t wrong — it’s just more work than necessary.</p>
